    css(fab, 'position:absolute;z-index:2147483647;width:42px;height:58px;border-radius:11px;border:1px solid rgba(160,205,255,.5);cursor:move;background:linear-gradient(170deg,#41558a 0%,#1e2a45 48%,#101728 100%);color:#eaf2ff;box-shadow:0 6px 20px rgba(8,16,36,.62),inset 0 1px 0 rgba(255,255,255,.26);display:flex;align-items:center;justify-content:center;touch-action:none;user-select:none;padding:0;overflow:visible;');
    fab.innerHTML = '<svg width="26" height="40" viewBox="0 0 24 34" fill="none" style="pointer-events:none;filter:drop-shadow(0 1px 2px rgba(0,0,0,.5));">'
      + '<rect x="1" y="1" width="22" height="32" rx="5.2" stroke="#d3e5ff" stroke-width="1.4"/>'
      + '<rect x="3.6" y="4.8" width="16.8" height="22.6" rx="2.4" fill="rgba(120,180,255,.2)" stroke="rgba(200,225,255,.7)" stroke-width="1"/>'
      + '<line x1="9.6" y1="3.1" x2="14.4" y2="3.1" stroke="#a9caff" stroke-width="1.2" stroke-linecap="round"/>'
      + '<circle cx="12" cy="30.1" r="1.05" fill="#a9caff"/>'
      + '</svg>';
    var badge = d.createElement('span');
    badge.id = 'hpBadge';
    css(badge, 'position:absolute;top:-6px;right:-7px;min-width:18px;height:18px;padding:0 5px;border-radius:999px;background:linear-gradient(160deg,#ff6b7d,#cf1036);color:#fff;font-size:11px;font-weight:700;line-height:18px;text-align:center;box-shadow:0 2px 8px rgba(207,16,54,.5);display:none;pointer-events:none;font-family:system-ui,-apple-system,sans-serif;letter-spacing:0;');
    fab.appendChild(badge);
    fab.title = '手机（按住拖动位置 ｜ 右上角是未读通知）';
    var panel = d.createElement('div');
    panel.id = 'hpPanel';
    panel.setAttribute('data-hp-gen', MY_GEN);
    css(panel, 'position:absolute;z-index:2147483646;width:min(360px,92vw);height:min(600px,80vh);background:transparent;border-radius:14px;overflow:hidden;display:none;box-shadow:0 12px 48px rgba(0,0,0,.5);');
    var ifr = d.createElement('iframe');
    ifr.id = 'hpFrame';
    css(ifr, 'width:100%;height:100%;border:none;background:#1a0f26;');
    ifr.dataset.loaded = '';
    panel.appendChild(ifr);
